# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MED ÇEŞİTLERİNİ SINIFLANDIRMA: ASLİ MED VE FER\'Î MED SEBEPLERİ</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Asli Med (Medd-i Tabiî)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Med Harfleri: ا (Elif) · و (Vav) · ي (Ya)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#334155">Med harfinden sonra «hemze» veya «sükûn»</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" fill="#334155">gelmediğinde oluşan doğal uzatmadır.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Uzatma Ölçüsü: 1 Elif Miktarı</text>\n  <text x="180" y="198" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e3a8a">قَالَ · يَقُولُ · قِيلَ · كِتَابٌ</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Fer\'î Med ve Sebeb-i Med (İki Sebep)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">1. Sebep: HEMZE (ء / أَ / إِ / أُ)</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#334155">➔ Medd-i Muttasıl (Aynı kelimede)</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#334155">➔ Medd-i Munfasıl (Ayrı kelimelerde)</text>\n  <text x="520" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">2. Sebep: SÜKÛN (Cezim ْ veya Şedde ّ)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#334155">➔ Medd-i Lâzım · Medd-i Ârız · Medd-i Lîn</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">1 eliften fazla (2-4 elif) uzatılarak okunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HEMZE SEBEBİYLE OLUŞAN MEDLER: MUTTASIL VE MUNFASIL</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Medd-i Muttasıl (Bitişik Med)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#713f12">Med harfi ile sebebi olan kırık hemze (ء)</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">AYNI KELİME İÇİNDE yan yana gelir.</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11.5" fill="#713f12">• Hükmü: Vaciptir (En az 2 - 4 elif uzatılır)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="15" font-weight="bold" fill="#854d0e">جَاءَ · السَّمَاءِ · سُوءَ · أُولَئِكَ</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#475569">Kırık hemze (ء) kelimenin ortasında/sonundadır.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Medd-i Munfasıl (Ayrık Med)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#581c87">Med harfi birinci kelimenin sonunda, uzun hemze (أ)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">İKİNCİ KELİMENİN BAŞINDA gelir.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11.5" fill="#581c87">• Hükmü: Caizdir (1 ile 4 elif arası uzatılır)</text>\n  <text x="520" y="172" text-anchor="middle" font-size="15" font-weight="bold" fill="#6b21a8">إِنَّا أَعْطَيْنَاكَ · يَا أَيُّهَا · قُوا أَنْفُسَكُمْ</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#475569">İki ayrı kelime sınırında karşılaşma gerçekleşir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜKÛN SEBEBİYLE OLUŞAN MEDLERE GENEL BAKIŞ (TASNİF)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Medd-i Lâzım</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#155e75">Med harfinden sonra durulsa da</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#155e75">geçilse de kaybolmayan</text>\n  <text x="125" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Lâzımî (kalıcı) sükûn</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#155e75">(cezim veya şedde) gelir.</text>\n  <text x="125" y="182" text-anchor="middle" font-size="14" font-weight="bold" fill="#164e63">الضَّالِّينَ · الحَاقَّةُ · الم</text>\n  <text x="125" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">4 Elif miktarı uzatmak vaciptir.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Medd-i Ârız</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#9f1239">Med harfinden sonra durak</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#9f1239">(vakıf) sebebiyle ortaya çıkan</text>\n  <text x="350" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Ârızî (geçici) sükûn</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11" fill="#9f1239">geldiğinde oluşur.</text>\n  <text x="350" y="182" text-anchor="middle" font-size="14" font-weight="bold" fill="#881337">الْعَالَمِينَ ➔ الْعَالَمِينْ</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#e11d48">Durulduğunda caiz olarak uzatılır.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Medd-i Lîn</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#9a3412">Üstünlü harften sonra gelen</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">cezimli وْ veya يْ (lîn harfi)</text>\n  <text x="575" y="134" text-anchor="middle" font-size="11" fill="#9a3412">ardından durak sebebiyle</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" fill="#9a3412">sükûn gelmesiyle oluşur.</text>\n  <text x="575" y="182" text-anchor="middle" font-size="14" font-weight="bold" fill="#7c2d12">قُرَيْشٍ · خَوْفٍ · الصَّيْفِ</text>\n  <text x="575" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ea580c">Yumuşak bir sesle uzatılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
